from bioblend.galaxy import GalaxyInstance
import json

gi = GalaxyInstance(url='https://usegalaxy.org', key='[REDACTED_GALAXY_API_KEY]')
hist_id = 'bbd44e69cb8906b5d2bece4bdb8cf67c'

# Get the tool to see its input structure
tool = gi.tools.show_tool('toolshed.g2.bx.psu.edu/repos/iuc/deseq2/deseq2/2.11.40.8+galaxy3')

# Look at the inputs section
inputs = tool.get('inputs', [])
def print_inputs(inputs, indent=0):
    for inp in inputs:
        prefix = '  ' * indent
        name = inp.get('name', '?')
        itype = inp.get('type', '?')
        label = inp.get('label', '')
        print(f'{prefix}{name} [{itype}] {label}')
        if itype == 'repeat':
            print_inputs(inp.get('inputs', []), indent+1)
        elif itype == 'conditional':
            print(f'{prefix}  test: {inp.get("test_param",{}).get("name","?")}')
            for case_name, case_inputs in inp.get('cases', {}).items():
                print(f'{prefix}  case {case_name}:')
                if isinstance(case_inputs, dict):
                    print_inputs(case_inputs.get('inputs', []), indent+2)
                else:
                    print_inputs(case_inputs, indent+2)
        elif itype == 'data':
            print(f'{prefix}  extensions: {inp.get("extensions", [])}, multiple: {inp.get("multiple", False)}')
        elif itype == 'select':
            opts = inp.get('options', [])
            if len(opts) <= 10:
                print(f'{prefix}  options: {opts}')
            else:
                print(f'{prefix}  options: {len(opts)} items')

print_inputs(inputs)
