                        {
                            "__index__": 1,
                            "factorLevel": "WL",
                            "countsFile": {
                                "src": "hda",
                                "id": "f9cad7b01a47213555982fd9e3ef7a2a"
                            }
                        }
                    ]
                }
            ]
        },
        "tximport": {
            "tximport_selector": "count"
        },
        "advanced_options": {
            "lfc_shrinkage_type": "apeglm",
            "outlier_filter_off": False,
            "auto_mean_filter_off": False,
            "prefilter_conditional": {
                "prefilter": ""
            }
        },
        "output_options": {
            "output_selector": "pdf",
            "alpha_ma": "0.05"
        }
    }

    # Try running with 21.01 format
    result = gi.tools.run_tool(
        history_id=hist_id,
        tool_id=tool_id,
        tool_inputs=tool_inputs,
        input_format='21.01'
